    if node['title'] == 'Plant 2103, Period 02: Products':
        for row in node['table']['rows']:
            prod, group, sub, loc, kg, opening = row
            products[prod] = {'kg': float(kg), 'opening': int(opening)}
        break
# load ledger data
orders_by_day = defaultdict(dict)
prod_production_by_day = defaultdict(dict)
for node in doc['nodes']:
    if node['title'] == 'Plant 2103, Period 02: Daily ledger':
        for row in node['table']['rows']:
            day = int(row[0])
            prod = row[2]
            prod_production_by_day[prod][day] = int(row[3])
            orders_by_day[day][prod] = int(row[4])
        break

# simulate
stock_prev = {p: products[p]['opening'] for p in products}
open_orders = []
results = {}
for day in range(15, 29):
    # production arrival
    for prod in products:
        qty = prod_production_by_day[prod].get(day, 0)
        if prod == 'SOS001L12P':
            if day == 15:
                qty = 0
            elif day == 18:
                qty = 11897
        stock_prev[prod] += qty
    # new orders join
    for prod, ord_qty in orders_by_day[day].items():
        if ord_qty > 0:
            open_orders.append({'prod': prod, 'qty': ord_qty, 'day': day})
    # dispatch
    capacity = C
    while capacity > 0 and open_orders:
        # sort orders
        open_orders.sort(key=lambda o: (o['day'], o['qty'], o['prod']))
        order = open_orders[0]
        prod = order['prod']
        weight = products[prod]['kg']
        max_units = min(order['qty'], int(capacity // weight), stock_prev[prod])
        if max_units <= 0:
            # try next order
            found = False
            for idx in range(1, len(open_orders)):
                o2 = open_orders[idx]
                prod2 = o2['prod']
                w2 = products[prod2]['kg']
                mu = min(o2['qty'], int(capacity // w2), stock_prev[prod2])
                if mu > 0:
                    open_orders[0], open_orders[idx] = open_orders[idx], open_orders[0]
                    found = True
                    break
            if not found:
                break
            continue
        order['qty'] -= max_units
        stock_prev[prod] -= max_units
        capacity -= max_units * weight
        if order['qty'] == 0:
            open_orders.pop(0)
    # backordered per prod
    backordered = defaultdict(int)
    for o in open_orders:
        backordered[o['prod']] += o['qty']
    results[day] = {
        'stock': stock_prev.copy(),
        'backordered': backordered.copy(),
    }

